import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../app/app_providers.dart';

class BusinessBrainActivityScreen extends ConsumerStatefulWidget { const BusinessBrainActivityScreen({super.key}); @override ConsumerState<BusinessBrainActivityScreen> createState() => _BusinessBrainActivityScreenState(); }
class _BusinessBrainActivityScreenState extends ConsumerState<BusinessBrainActivityScreen> {
  late Future<List<Map<String, dynamic>>> activity;
  @override void initState() { super.initState(); activity = _load(); }
  Future<List<Map<String, dynamic>>> _load() async { final workspace = ref.read(workspaceControllerProvider).value; if (workspace == null) return []; return ref.read(businessBrainRepositoryProvider).list('audit_logs', workspace.id, orderBy: 'created_at'); }
  void reload() => setState(() => activity = _load());
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Activity'), actions: [IconButton(tooltip: 'Refresh', onPressed: reload, icon: const Icon(Icons.refresh))]), body: FutureBuilder<List<Map<String, dynamic>>>(future: activity, builder: (context, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); if (snapshot.hasError) return _StateMessage(text: 'Activity could not be loaded: ${snapshot.error}', retry: reload); final events = snapshot.data!.reversed.toList(); if (events.isEmpty) return const _StateMessage(text: 'No workspace activity has been recorded yet.'); return RefreshIndicator(onRefresh: () async => reload(), child: ListView(padding: const EdgeInsets.all(16), children: [for (final event in events) Card(child: ListTile(leading: const Icon(Icons.history), title: Text(_humanize('${event['event_type'] ?? 'Workspace update'}')), subtitle: Text('${event['entity_type'] ?? 'Workspace'}${event['created_at'] == null ? '' : ' • ${event['created_at']}'}'), onTap: () => showDialog<void>(context: context, builder: (ctx) => AlertDialog(title: Text(_humanize('${event['event_type'] ?? 'Workspace update'}')), content: SingleChildScrollView(child: Text('Record: ${event['entity_type'] ?? 'Workspace'}\nID: ${event['entity_id'] ?? '—'}\nDetails: ${event['metadata'] ?? '—'}')), actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Close'))]))))])); }));
  String _humanize(String value) => value.replaceAll('_', ' ').split(' ').map((word) => word.isEmpty ? word : '${word[0].toUpperCase()}${word.substring(1)}').join(' ');
}
class _StateMessage extends StatelessWidget { const _StateMessage({required this.text, this.retry}); final String text; final VoidCallback? retry; @override Widget build(BuildContext context) => Center(child: Padding(padding: const EdgeInsets.all(28), child: Column(mainAxisSize: MainAxisSize.min, children: [Text(text, textAlign: TextAlign.center), if (retry != null) OutlinedButton.icon(onPressed: retry, icon: const Icon(Icons.refresh), label: const Text('Retry'))]))); }
